import {
  type AccountRef,
  accountRefSchema,
  type AssetRef,
  assetRefSchema,
  type LaunchLog,
} from "@binference/plugin-sdk";

// The Portal's logs of two BSC transactions, recorded from 48 Club's public node on 2026-10-19,
// with only the events the venue declares for the launch feed: a launch with its first buy, and a
// bundle that bought two tokens launched before.

const account = (address: string): AccountRef => accountRefSchema.parse(`eip155:56:${address}`);

/** The token the recorded launch created, its creator, and the quote token its logs name. */
export const recordedLaunch: {
  readonly token: AssetRef;
  readonly creator: AccountRef;
  readonly quoteToken: AssetRef;
} = {
  token: assetRefSchema.parse("eip155:56/erc20:0xAa5F0C03EF84A93Ed6bf75a5C719057211777777"),
  creator: account("0xDacEB1fF5956d76A8c69EbAf596b1a1260B608a7"),
  quoteToken: assetRefSchema.parse("eip155:56/erc20:0x4902C5ebc598265Ed2212b559B042De8a5Eeec3f"),
};

